const raw = $input.first().json.text;

try {
  // Парсим JSON
  const parsed = JSON.parse(raw);

  // Проверяем, что получили массив
  const items = Array.isArray(parsed)
    ? parsed
    : [];

  // Возвращаем результат
  return [
    {
      json: {
        items: items,
        total: items.length,
        status: items.length > 0 ? "success" : "empty"
      }
    }
  ];

} catch (error) {

  return [
    {
      json: {
        items: [],
        total: 0,
        status: "empty",
        error: error.message
      }
    }
  ];
}

